#include <vector>
#include <algorithm>
#include <climits>

using namespace std;

class Solution {
public:
    int minDistance(vector<int>& houses, int k) {
        sort(houses.begin(), houses.end());
        int n = houses.size();
        vector<vector<int>> cost(n, vector<int>(n, 0));

        for (int i = 0; i < n; ++i)
            for (int j = i; j < n; ++j) {
                int mid = (i + j) / 2;
                for (int x = i; x <= j; ++x)
                    cost[i][j] += abs(houses[x] - houses[mid]);
            }

        vector<vector<int>> dp(n + 1, vector<int>(k + 1, INT_MAX));
        dp[0][0] = 0;

        for (int i = 1; i <= n; ++i)
            for (int j = 1; j <= k; ++j)
                for (int m = 0; m < i; ++m)
                    if (dp[m][j - 1] != INT_MAX)
                        dp[i][j] = min(dp[i][j], dp[m][j - 1] + cost[m][i - 1]);

        return dp[n][k];
    }
};
